<?php
function register_notification_routes($router,$pdo,$config){
 $router->get('/notifications',function()use($pdo,$config){
    $uid=Security::requireUser();$svc=new NotificationService($pdo);
    $page=isset($_GET['page'])&&is_scalar($_GET['page'])?max(1,(int)$_GET['page']):1;
    $filter=isset($_GET['read'])&&is_string($_GET['read'])&&in_array($_GET['read'],array('unread','read'),true)?$_GET['read']:'';
    $types=array('order_paid'=>'付款通知','order_delivered'=>'交付通知','order_refunded'=>'退款通知','ticket_update'=>'工单更新','ticket_reply'=>'工单回复','ticket_closed'=>'工单关闭','feedback_review'=>'反馈审核','feedback_progress'=>'反馈进度','system'=>'系统消息');
    $type=isset($_GET['type'])&&is_string($_GET['type'])&&isset($types[$_GET['type']])?$_GET['type']:'';
    $data=$svc->paginate($uid,$page,20,$filter,$type);
    $qs=function($r,$t,$p=1){$v=array();if($r!=='')$v[]='read='.rawurlencode($r);if($t!=='')$v[]='type='.rawurlencode($t);if($p>1)$v[]='page='.(int)$p;return '/notifications'.($v?'?'.implode('&',$v):'');};
    $fields='<input type="hidden" name="read" value="'.e($filter).'"/><input type="hidden" name="type" value="'.e($type).'"/><input type="hidden" name="page" value="'.(int)$data['page'].'"/>';
    $rows='';$previews='';$messageIndex=0;
    foreach($data['items'] as $n){
        $path=$svc->targetPath($n);$previewId='message-'.(int)$n['id'];
        $typeLabel=isset($types[$n['type']])?$types[$n['type']]:'账户消息';
        $tone=strpos($n['type'],'ticket_')===0?'ticket':(strpos($n['type'],'feedback_')===0?'feedback':($n['type']==='system'?'system':($n['type']==='order_delivered'?'delivered':'order')));
        $icon=$tone==='ticket'?'tickets':($tone==='feedback'?'help':($tone==='system'?'bell':'orders'));
        $unread=empty($n['read_at']);
        $previews.='<button type="button" class="notification-preview notification-tone-'.$tone.($messageIndex===0?' is-selected':'').'" data-message-target="'.$previewId.'" aria-controls="'.$previewId.'" aria-pressed="'.($messageIndex===0?'true':'false').'"><span class="notification-preview-icon" aria-hidden="true">'.user_nav_icon($icon).'</span><span class="notification-preview-copy"><b>'.e($n['title']).'</b><small>'.e(mb_substr($n['content'],0,60,'UTF-8')).'</small><time>'.e($n['created_at']).'</time></span>'.($unread?'<i aria-label="未读"></i>':'').'</button>';
        $messageIndex++;
        $rows.='<article id="'.$previewId.'" class="notification-item'.($unread?' unread':'').'"><header class="notification-detail-heading"><span class="notification-type-label">'.e($typeLabel).'</span><h2>'.e($n['title']).'</h2><time>'.e($n['created_at']).'</time></header><p class="notification-detail-content">'.nl2br(e($n['content'])).'</p>'.($path?'<div class="notification-related"><span>相关内容</span>'.(!empty($n['order_no'])?'<p>订单编号：'.e($n['order_no']).'</p>':'').'<a href="'.e($path).'">查看详情 →</a></div>':'').($unread?'<form class="notification-read-action" method="post" action="/notifications/'.(int)$n['id'].'/read">'.csrf_field().$fields.'<button class="secondary-button" type="submit">标为已读</button></form>':'<span class="notification-read-label">已读</span>').'</article>';
    }
    $tabs='<a'.($type===''?' class="service-ui-selected" aria-current="page"':'').' href="'.e($qs($filter,'')).'">全部消息</a>';
    foreach($types as $key=>$label)$tabs.='<a'.($type===$key?' class="service-ui-selected" aria-current="page"':'').' href="'.e($qs($filter,$key)).'">'.e($label).'</a>';
    $readTabs='';foreach(array(''=>'全部状态','unread'=>'未读','read'=>'已读') as $key=>$label)$readTabs.='<a'.($filter===$key?' class="service-ui-selected" aria-current="page"':'').' href="'.e($qs($key,$type)).'">'.$label.'</a>';
    $empty='<div class="empty service-ui-empty"><h2>'.($filter!==''||$type!==''?'当前筛选下暂无消息':'暂无消息').'</h2><p>订单、反馈和工单的相关消息将在这里展示。</p><a class="secondary-button" href="'.($filter!==''||$type!==''?'/notifications':'/announcements').'">'.($filter!==''||$type!==''?'查看全部消息':'查看系统公告').'</a></div>';
    $body='<div class="notifications-page account-reference-messages"><header class="ux-page-head"><div><h1>消息中心</h1><p>接收订单状态、系统通知与工单消息，重要进展集中查看。</p></div><form method="post" action="/notifications/read-all">'.csrf_field().$fields.'<button class="secondary-button" type="submit">全部标为已读</button></form></header><nav class="notification-filters notification-type-tabs" aria-label="消息类型">'.$tabs.'</nav><div class="notification-toolbar"><nav class="notification-read-filters" aria-label="已读状态">'.$readTabs.'</nav><a href="/announcements">系统公告 →</a></div><div class="notification-split'.($rows===''?' notification-split-empty':'').'"><nav class="notification-previews" aria-label="选择消息">'.$previews.'</nav><section class="notification-list" aria-label="消息内容">'.($rows?:$empty).'</section></div><nav class="service-ui-pagination" aria-label="消息分页"><span>共 '.(int)$data['total'].' 条 · 第 '.(int)$data['page'].' / '.(int)$data['pages'].' 页</span> '.($data['page']>1?'<a rel="prev" href="'.e($qs($filter,$type,$data['page']-1)).'">上一页</a> ':'').($data['page']<$data['pages']?'<a rel="next" href="'.e($qs($filter,$type,$data['page']+1)).'">下一页</a>':'').'</nav></div>';
    $body.='<script>(function(){var root=document.querySelector(".account-reference-messages"),buttons=root.querySelectorAll("[data-message-target]"),items=root.querySelectorAll(".notification-list>.notification-item"),wide=window.matchMedia("(min-width:1101px)"),selected=buttons.length?buttons[0].dataset.messageTarget:"";function render(){root.classList.add("messages-enhanced");items.forEach(function(item){item.hidden=wide.matches&&item.id!==selected});buttons.forEach(function(button){var active=button.dataset.messageTarget===selected;button.classList.toggle("is-selected",active);button.setAttribute("aria-pressed",String(active))})}buttons.forEach(function(button){button.addEventListener("click",function(){selected=button.dataset.messageTarget;render()})});wide.addEventListener("change",render);render()})();</script>';
    page('消息中心',$body,$config);
 });
 $router->post('/notifications/{id}/read',function($id)use($pdo){$uid=Security::requireUser();post_csrf();(new NotificationService($pdo))->markRead($uid,(int)$id);$r=isset($_POST['read'])&&is_string($_POST['read'])&&in_array($_POST['read'],array('unread','read'),true)?$_POST['read']:'';$t=isset($_POST['type'])&&is_string($_POST['type'])&&in_array($_POST['type'],array('feedback_review','feedback_progress','ticket_update','ticket_reply','ticket_closed','order_paid','order_delivered','order_refunded','system'),true)?$_POST['type']:'';$p=isset($_POST['page'])&&is_scalar($_POST['page'])?max(1,(int)$_POST['page']):1;redirect('/notifications?read='.rawurlencode($r).'&type='.rawurlencode($t).'&page='.$p);});
 $router->post('/notifications/read-all',function()use($pdo){$uid=Security::requireUser();post_csrf();(new NotificationService($pdo))->markAllRead($uid);$r=isset($_POST['read'])&&is_string($_POST['read'])&&in_array($_POST['read'],array('unread','read'),true)?$_POST['read']:'';$t=isset($_POST['type'])&&is_string($_POST['type'])&&in_array($_POST['type'],array('feedback_review','feedback_progress','ticket_update','ticket_reply','ticket_closed','order_paid','order_delivered','order_refunded','system'),true)?$_POST['type']:'';$p=isset($_POST['page'])&&is_scalar($_POST['page'])?max(1,(int)$_POST['page']):1;redirect('/notifications?read='.rawurlencode($r).'&type='.rawurlencode($t).'&page='.$p);});
}
